    public void testCreateDataFrame() {
        // Test creating a DataFrame with 3 columns and 4 rows
        DataFrame df = new DataFrame("Column1", "Column2", "Column3");
        assertEquals(3, df.getNumberOfColumns());
        assertEquals(4, df.getNumberOfRows());

        // Test accessing columns by name
        System.out.println(df.getColumn("Column1"));  // Output: Column1
        System.out.println(df.getColumn("Column2"));  // Output: Column2
        System.out.println(df.getColumn("Column3"));  // Output: Column3

        // Test accessing rows by index
        DataFrame dfCopy = (DataFrame) df.cloneStructure();
        assertEquals(4, dfCopy.getNumberOfRows());
        for (int i = 0; i < 4; i++) {
            System.out.println(dfCopy.getRow(i));
        }
    }

    @Test
    public void testJoin() {
        // Test joining two DataFrames based on a common column
        DataFrame df1 = new DataFrame("ColumnA", "ColumnB");
        DataFrame df2 = new DataFrame("ColumnC", "ColumnD");

        DfJoin joinDescriptor = new DfJoin(df1, "ColumnA", df2, "ColumnC");
        String result = join(joinDescriptor);
        assertEquals(3, result.getNumberOfRows());

        // Test joining two DataFrames based on different columns
        df1 = new DataFrame("ColumnE", "ColumnF");
        df2 = new DataFrame("ColumnG", "ColumnH");

        DfJoin joinDescriptor2 = new DfJoin(df1, "ColumnA", df2, "ColumnI");
        String result2 = join(joinDescriptor2);
        assertEquals(3, result2.getNumberOfRows());
    }

